args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/Rosaura_at_10_O'Clock> <http://dbpedia.org/resource/Uncle's_New_Blazer> }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?deathDate .
}
ORDER BY DESC(?deathDate)
LIMIT 1

